// Check 07 (#995 gap 1, G16-adapter-mounts call 1): an app calls a generated adapter through a call step, end to end.
//
// Seven adapters are generated by the real command (`ortho new adapter <name> --from-openapi`) into a copy of acme and mounted:
// `rates` (mounted as `pricing`) and `fx-rates` (as `fx-backup`), both secured at the top of their description, `open` (no
// security), `scoped` (secured on its one operation only), `anonymous` (a scheme, and only the anonymous requirement `[{}]`), `lax`
// (`[{}, { bearer: [] }]`, a key optional) and `bridge` (Bridge's shape: an `apiKey` scheme in a header, required at the top).
// `rate.quote` and `rate.backup` call `quotes.get` on `pricing` and `fx-backup`;
// `rate.stray` calls `pricing` and maps to the app's own `RateUnavailable`, which the call does not declare. The handlers are
// written here, not scaffolded: each passes the call's one input object and maps the client's failure to its namesake among the
// adapter's four errors (`RatesApiFailure { status }`, `RatesInputRefused`, `RatesAnswerRefused`, `RatesUnreachable`), imported
// from the adapter's package.
//
// The contract judged (G16-adapter-mounts call 1):
//  - a generated adapter declares stored runtime secrets `baseUrl`, and `apiKey` when its description requires security anywhere,
//    so each mount reads `<MOUNT>_BASE_URL` and `<MOUNT>_API_KEY`, named by the mount (dashes as underscores), never the package;
//  - a call step runs that adapter's `client({ baseUrl, token: apiKey })`, each mount with its own URL and key;
//  - `ORTHO_STAND_<MOUNT>` wins over `<MOUNT>_BASE_URL`;
//  - every generated call declares its adapter's four errors, which an operation lists and refuses with; a mapping to an error the
//    call does not declare (the app's own) stays a defect;
//  - no base URL is a defect: 500, nothing sent, never a default from `servers` (the defect names `<MOUNT>_BASE_URL` on its span,
//    which no collector reads here: a known limit), and no key value reaches the Worker's log.
//
// The world gets the values as secret bindings (`Worlds.start`'s `secretEnv`), as an environment's `secrets.env` gives them.
import { createServer, type IncomingMessage } from "node:http";
import { mkdirSync, readFileSync, readdirSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { Effect } from "effect";
import { Worlds } from "@orthograph/prove";
import { afterEach, describe, expect, it } from "vitest";
import { acme, copyOf, nothingRunning } from "../layer1/support.ts";
import { rowsOf, run } from "./secrets-support.ts";

// ---- the descriptions the adapters are generated from ----

// `schemes`: a scheme declared, and only the anonymous requirement `[{}]`, so nothing requires a key. `optional`: `[{}, { bearer: [] }]`,
// a key optional, which still requires one. `bridge`: Bridge's own shape, an `apiKey` scheme in its `Api-Key` header, required at the top.
type Secured = "top" | "operation" | "none" | "schemes" | "optional" | "bridge";
const schemeOf = (secured: Secured) => (secured === "bridge" ? "ApiKey" : "bearer");
const securityOf = (secured: Secured) =>
  secured === "top" || secured === "bridge" ? [{ [schemeOf(secured)]: [] }]
    : secured === "schemes" ? [{}]
      : secured === "optional" ? [{}, { bearer: [] }]
        : undefined;
const spec = (title: string, secured: Secured, path: string) => ({
  openapi: "3.0.3",
  info: { title, version: "1.0.0" },
  // A real-looking production server: a build that falls back to it would leave the world. `.invalid` never resolves.
  servers: [{ url: `https://${title.toLowerCase()}.example.invalid/v1` }],
  ...(secured === "none" ? {} : { components: { securitySchemes: secured === "bridge"
    ? { ApiKey: { type: "apiKey", in: "header", name: "Api-Key" } }
    : { bearer: { type: "http", scheme: "bearer" } } } }),
  ...(securityOf(secured) === undefined ? {} : { security: securityOf(secured) }),
  paths: {
    // A call that sorts before `quotes.get`, so a build that wires or declares only an adapter's first call is seen.
    [`/${path}/{pair}/check`]: { get: { operationId: "quotes/check", parameters: [{ name: "pair", in: "path", required: true, schema: { type: "string" } }], responses: { "204": { description: "Known" } } } },
    [`/${path}/{pair}`]: {
      get: {
        operationId: "quotes/get",
        ...(secured === "operation" ? { security: [{ bearer: [] }] } : {}),
        parameters: [
          { name: "pair", in: "path", required: true, schema: { type: "string" } },
          { name: "amount", in: "query", required: true, schema: { type: "integer" } },
        ],
        responses: { "200": { description: "A quote", content: { "application/json": { schema: {
          type: "object", required: ["pair", "rate"], properties: { pair: { type: "string" }, rate: { type: "string" } } } } } } },
      },
    },
  },
});

// ---- the app ----

const THING = `import { Blueprint } from "orthograph";

export const Rate = Blueprint.thing({ description: "A rate asked of a mounted adapter.", fields: { id: Blueprint.id("rte") }, code: "RT" });
`;
const ERRORS = `import { Blueprint } from "orthograph";

export class RateUnavailable extends Blueprint.error({ reason: Blueprint.text({ max: 200 }) }, { exit: 61 }) {}
`;
const mountOf = (name: string) => `import { Blueprint } from "orthograph";
import adapter from "@orthograph/${name}";

export default Blueprint.use(adapter, (a) => [a.include(a.calls.quotes.get)]);
`;
/** An adapter's name as its errors' prefix: `fx-rates` is `FxRates`. */
const pascalOf = (name: string) => name.split("-").map((w) => w[0]!.toUpperCase() + w.slice(1)).join("");
/** The adapter's four errors by the signed-off names: `Rates` for `@orthograph/rates`. */
const FOUR = ["ApiFailure", "InputRefused", "AnswerRefused", "Unreachable"] as const;
const verbOf = (mount: string, pkg: string, own = false) => {
  const P = pascalOf(pkg);
  // An operation declares every error its call may fail with (ortho check refuses one that doesn't); `own` adds the app's error too.
  const four = FOUR.map((f) => `${P}${f}`);
  const errors = own ? [...four, "RateUnavailable"] : four;
  return `import { Blueprint } from "orthograph";
${own ? 'import { RateUnavailable } from "../errors.ts";\n' : ""}import { ${four.join(", ")} } from "@orthograph/${pkg}";
import adapter from "../../../adapters/${mount}.ts";
import { Rate } from "../thing.ts";

export default Blueprint.operation(Rate, {
  description: "Ask the ${mount} mount for a rate.",
  payload: { pair: Blueprint.text({ max: 20 }), amount: Blueprint.uint(32) },
  answer: { rate: Blueprint.text({ max: 40 }) },
  errors: [${errors.join(", ")}],
  allowed: [Blueprint.anyone],
  steps: { price: Blueprint.step.call(adapter.calls.quotes.get) },
});
`;
};
// The handler: the call's one input object (a uint is a string on the wire, a bigint in code: the service takes a number), and the one mapping. Typed loosely, so the check does not pin the step's generated type.
const handlerOf = (verb: string, pkg: string | null) => {
  const P = pkg === null ? "" : pascalOf(pkg);
  const mapping = pkg === null
    ? "(_failure: unknown) => new RateUnavailable({ reason: \"the app's own error, which the call does not declare\" })"
    : `(failure: unknown) => {
    const f = failure as { readonly _tag?: string; readonly status?: number };
    switch (f._tag) {
      case "ApiFailure": return new ${P}ApiFailure({ status: BigInt(f.status ?? 0) } as never);
      case "InputRefused": return new ${P}InputRefused({} as never);
      case "AnswerRefused": return new ${P}AnswerRefused({} as never);
      default: return new ${P}Unreachable({} as never);
    }
  }`;
  return `import { Effect } from "effect";
${pkg === null ? 'import { RateUnavailable } from "../../blueprint/things/rate/errors.ts";' : `import { ${FOUR.map((f) => `${P}${f}`).join(", ")} } from "@orthograph/${pkg}";`}
import type { Handler } from "../../generated/server/handlers/rate/${verb}.ts";

const handler = ((payload: { readonly pair: string; readonly amount: bigint | number | string }, { steps }: { readonly steps: Record<string, (...args: ReadonlyArray<unknown>) => Effect.Effect<unknown, unknown>> }) =>
  steps["price"]!([payload.pair === "NOAMOUNT" ? { pair: payload.pair } : { pair: payload.pair, amount: Number(payload.amount) }], ${mapping}).pipe(
    Effect.map((answer) => ({ rate: String((answer as { readonly rate?: unknown }).rate) })),
  )) as unknown as Handler;

export default handler;
`;
};

// Each package, the name it is mounted under, where its description says security is, and its path. `rates` is mounted as `pricing`
// and `fx-rates` as `fx-backup`, so a name taken from the package, or kept with its dash, is wrong; `fx-rates`'s errors are
// `FxRates…`. `scoped` is secured on its operation only; `anonymous` declares a scheme that nothing requires; `lax` makes the
// key optional, and `bridge` is shaped as Bridge's description is (both still require one).
const ADAPTERS = {
  rates: { secured: "top", mount: "pricing", path: "quotes" },
  "fx-rates": { secured: "top", mount: "fx-backup", path: "fx-quotes" },
  open: { secured: "none", mount: "open", path: "quotes" },
  scoped: { secured: "operation", mount: "scoped", path: "quotes" },
  anonymous: { secured: "schemes", mount: "anonymous", path: "quotes" },
  lax: { secured: "optional", mount: "lax", path: "quotes" },
  bridge: { secured: "bridge", mount: "bridge", path: "quotes" },
} as const;

interface App { readonly root: string; readonly remove: () => void }
const apps: Array<App> = [];
afterEach(() => { for (const app of apps.splice(0)) app.remove(); });

const ortho = (root: string, ...args: ReadonlyArray<string>) => {
  const said = run(root, ...args);
  expect(said.status, `ortho ${args.join(" ")}:\n${said.out}`).toBe(0);
  return said;
};

/** A copy of acme with the adapters generated, installed and mounted, and `rate.quote` (pricing) and `rate.backup` (fx). */
const app = (): App => {
  const copy = copyOf(acme);
  apps.push(copy);
  const { root } = copy;
  // The copy's @orthograph is acme's, linked whole: make it a folder of links, so the generated plugins can join it.
  const scope = join(root, "node_modules/@orthograph");
  rmSync(scope);
  mkdirSync(scope);
  for (const entry of readdirSync(join(acme, "node_modules/@orthograph"))) symlinkSync(join(acme, "node_modules/@orthograph", entry), join(scope, entry));
  const specs = join(root, ".specs");
  mkdirSync(specs);
  const pkg = JSON.parse(readFileSync(join(root, "package.json"), "utf8")) as { dependencies: Record<string, string> };
  for (const [name, { secured, mount, path }] of Object.entries(ADAPTERS)) {
    writeFileSync(join(specs, `${name}.json`), JSON.stringify(spec(name[0]!.toUpperCase() + name.slice(1), secured, path)));
    ortho(root, "new", "adapter", name, "--from-openapi", join(specs, `${name}.json`));
    symlinkSync(join(root, "plugins", name), join(scope, name));
    pkg.dependencies[`@orthograph/${name}`] = "0.0.0";
    mkdirSync(join(root, "blueprint/adapters"), { recursive: true });
    writeFileSync(join(root, `blueprint/adapters/${mount}.ts`), mountOf(name));
  }
  writeFileSync(join(root, "package.json"), JSON.stringify(pkg, null, 2));
  mkdirSync(join(root, "blueprint/things/rate/verbs"), { recursive: true });
  writeFileSync(join(root, "blueprint/things/rate/thing.ts"), THING);
  writeFileSync(join(root, "blueprint/things/rate/errors.ts"), ERRORS);
  writeFileSync(join(root, "blueprint/things/rate/verbs/quote.ts"), verbOf("pricing", "rates"));
  writeFileSync(join(root, "blueprint/things/rate/verbs/backup.ts"), verbOf("fx-backup", "fx-rates"));
  writeFileSync(join(root, "blueprint/things/rate/verbs/stray.ts"), verbOf("pricing", "rates", true));
  ortho(root, "generate");
  mkdirSync(join(root, "src/rate"), { recursive: true });
  writeFileSync(join(root, "src/rate/quote.ts"), handlerOf("quote", "rates"));
  writeFileSync(join(root, "src/rate/backup.ts"), handlerOf("backup", "fx-rates"));
  writeFileSync(join(root, "src/rate/stray.ts"), handlerOf("stray", null));
  ortho(root, "generate");
  return copy;
};

// ---- a service that records what reached it ----

interface Seen { readonly method: string; readonly url: string; readonly authorization: string | null }
interface Service { readonly url: string; readonly seen: Array<Seen>; readonly close: () => Promise<void> }
/** `GET <prefix>/<path>/<pair>?amount=`: 401 without a bearer, 503 for the pair FAIL, an answer without its rate for MISFIT, a rate otherwise. */
const service = async (name: string, path = "quotes"): Promise<Service> => {
  const seen: Array<Seen> = [];
  const server = createServer((request: IncomingMessage, response) => {
    const authorization = request.headers.authorization ?? null;
    seen.push({ method: request.method ?? "", url: request.url ?? "", authorization });
    const send = (status: number, body: unknown) => { response.writeHead(status, { "content-type": "application/json" }); response.end(JSON.stringify(body)); };
    const pair = new RegExp(`^/v1/${path}/([^/?]+)`).exec(request.url ?? "")?.[1];
    if (authorization === null || !authorization.startsWith("Bearer ")) return send(401, { error: "no key" });
    if (pair === undefined) return send(404, { error: "no such path" });
    if (pair === "FAIL") return send(503, { error: "down" });
    if (pair === "MISFIT") return send(200, { pair });
    return send(200, { pair, rate: `${name}-1.0842` });
  });
  await new Promise<void>((ready) => server.listen(0, "127.0.0.1", ready));
  const port = (server.address() as { port: number }).port;
  return { url: `http://127.0.0.1:${port}`, seen, close: () => new Promise<void>((done) => { server.closeAllConnections(); server.close(() => done()); }) };
};

const ask = async (url: string, verb: "quote" | "backup" | "stray", body: unknown) => {
  const response = await fetch(`${url}/rate/${verb}`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
  const text = await response.text();
  return { status: response.status, body: (text.startsWith("{") ? JSON.parse(text) : text) as unknown };
};

/** The world with these secret bindings; `use` gets its url and the path of its log. `after` is the whole log, read once the world stopped. */
const inWorld = async <A>(root: string, name: string, secretEnv: Record<string, string>, use: (url: string, log: string) => Promise<A>): Promise<A & { readonly after: string }> => {
  let path = "";
  const got = await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
    const world = yield* Worlds.start({ root, port: 0, name, secretEnv });
    path = world.log;
    return yield* Effect.promise(() => use(world.url, world.log));
  })));
  return { ...got, after: readFileSync(path, "utf8") };
};

describe("07 a generated adapter names its base URL and key per mount", () => {
  it("ortho secrets lists <MOUNT>_BASE_URL for every generated mount and <MOUNT>_API_KEY only where the description requires security, each stored and runtime", () => {
    const { root } = app();
    const rows = rowsOf(ortho(root, "secrets").out);
    const ours = rows.filter((r) => /^(PRICING|RATES|FX|FX_RATES|FX_BACKUP|OPEN|SCOPED|ANONYMOUS|LAX|BRIDGE)_/.test(r.name));
    expect(ours.map((r) => r.name).sort()).toEqual([
      "ANONYMOUS_BASE_URL", "BRIDGE_API_KEY", "BRIDGE_BASE_URL", "FX_BACKUP_API_KEY", "FX_BACKUP_BASE_URL", "LAX_API_KEY",
      "LAX_BASE_URL", "OPEN_BASE_URL", "PRICING_API_KEY", "PRICING_BASE_URL", "SCOPED_API_KEY", "SCOPED_BASE_URL",
    ]);
    for (const r of ours) expect([r.name, r.how, r.kind]).toEqual([r.name, "stored", "runtime"]);
  });
});

describe("07 a call step reaches a generated adapter in a world", () => {
  it("each mount sends to its own base URL with its own key, the input's path and query, and answers; a 503, a misfit answer and a missing input are refused as the adapter's errors; the app's own error is a defect", async () => {
    const { root } = app();
    const rates = await service("rates");
    const fx = await service("fx", "fx-quotes");
    try {
      const got = await inWorld(root, "m2-07-calls", { PRICING_BASE_URL: `${rates.url}/v1`, PRICING_API_KEY: "rates-key-7f3a", FX_BACKUP_BASE_URL: `${fx.url}/v1`, FX_BACKUP_API_KEY: "fx-key-91c2" }, async (url, log) => ({
        quote: await ask(url, "quote", { pair: "EURUSD", amount: "100" }),
        backup: await ask(url, "backup", { pair: "GBPJPY", amount: "7" }),
        down: await ask(url, "quote", { pair: "FAIL", amount: "1" }),
        misfit: await ask(url, "quote", { pair: "MISFIT", amount: "2" }),
        stray: await ask(url, "stray", { pair: "FAIL", amount: "3" }),
        noAmount: await ask(url, "quote", { pair: "NOAMOUNT", amount: "4" }),
        log: readFileSync(log, "utf8"),
      }));
      for (const log of [got.log, got.after]) {
        expect(log).not.toContain("rates-key-7f3a");
        expect(log).not.toContain("fx-key-91c2");
      }
      expect(got.noAmount).toMatchObject({ status: 422, body: { _tag: "RatesInputRefused" } });
      expect(got.quote).toEqual({ status: 200, body: { rate: "rates-1.0842" } });
      expect(got.backup).toEqual({ status: 200, body: { rate: "fx-1.0842" } });
      expect(got.down).toMatchObject({ status: 422, body: { _tag: "RatesApiFailure" } });
      expect(String((got.down.body as { status?: unknown }).status)).toBe("503");
      expect(got.misfit).toMatchObject({ status: 422, body: { _tag: "RatesAnswerRefused" } });
      expect(got.stray.status, JSON.stringify(got.stray.body)).toBe(500);
      expect(JSON.stringify(got.stray.body)).not.toContain("RateUnavailable");
      expect(rates.seen).toEqual([
        { method: "GET", url: "/v1/quotes/EURUSD?amount=100", authorization: "Bearer rates-key-7f3a" },
        { method: "GET", url: "/v1/quotes/FAIL?amount=1", authorization: "Bearer rates-key-7f3a" },
        { method: "GET", url: "/v1/quotes/MISFIT?amount=2", authorization: "Bearer rates-key-7f3a" },
        { method: "GET", url: "/v1/quotes/FAIL?amount=3", authorization: "Bearer rates-key-7f3a" },
      ]);
      expect(fx.seen).toEqual([{ method: "GET", url: "/v1/fx-quotes/GBPJPY?amount=7", authorization: "Bearer fx-key-91c2" }]);
    } finally {
      await rates.close();
      await fx.close();
    }
    nothingRunning(root);
  });

  it("with no key the service's 401 reaches the handler's mapping; a stand-in alone is an address; with neither the call is a defect that sends nothing", async () => {
    const { root } = app();
    const rates = await service("rates");
    const fx = await service("fx", "fx-quotes");
    try {
      // pricing has only its stand-in, which is enough; fx-backup has a key and no address, and pricing's stand-in is not its.
      const got = await inWorld(root, "m2-07-missing", { ORTHO_STAND_PRICING: `${rates.url}/v1`, FX_BACKUP_API_KEY: "fx-key-91c2" }, async (url, log) => {
        const keyless = await ask(url, "quote", { pair: "EURUSD", amount: "100" });
        const nowhere = await ask(url, "backup", { pair: "GBPJPY", amount: "7" });
        return { keyless, nowhere, log: readFileSync(log, "utf8") };
      });
      expect(got.keyless).toMatchObject({ status: 422, body: { _tag: "RatesApiFailure" } });
      expect(String((got.keyless.body as { status?: unknown }).status)).toBe("401");
      expect(rates.seen).toEqual([{ method: "GET", url: "/v1/quotes/EURUSD?amount=100", authorization: null }]);
      expect(got.nowhere.status).toBe(500);
      expect(JSON.stringify(got.nowhere.body)).not.toMatch(/FxApiFailure|FxUnreachable/);
      expect(fx.seen).toEqual([]);
      for (const log of [got.log, got.after]) expect(log).not.toContain("fx-key-91c2");
    } finally {
      await rates.close();
      await fx.close();
    }
    nothingRunning(root);
  });

  it("ORTHO_STAND_<MOUNT> wins over <MOUNT>_BASE_URL for that mount only, a dashed mount's name with underscores", async () => {
    const { root } = app();
    const real = await service("real");
    const stand = await service("stand");
    const fx = await service("fx", "fx-quotes");
    const fxStand = await service("fx-stand", "fx-quotes");
    try {
      const got = await inWorld(root, "m2-07-stand", {
        PRICING_BASE_URL: `${real.url}/v1`, PRICING_API_KEY: "rates-key-7f3a", ORTHO_STAND_PRICING: `${stand.url}/v1`, FX_BACKUP_BASE_URL: `${fx.url}/v1`, FX_BACKUP_API_KEY: "fx-key-91c2", ORTHO_STAND_FX_BACKUP: `${fxStand.url}/v1`,
      }, async (url) => ({ quote: await ask(url, "quote", { pair: "EURUSD", amount: "100" }), backup: await ask(url, "backup", { pair: "GBPJPY", amount: "7" }) }));
      expect(got.quote).toEqual({ status: 200, body: { rate: "stand-1.0842" } });
      expect(got.backup).toEqual({ status: 200, body: { rate: "fx-stand-1.0842" } });
      expect(real.seen).toEqual([]);
      expect(stand.seen).toEqual([{ method: "GET", url: "/v1/quotes/EURUSD?amount=100", authorization: "Bearer rates-key-7f3a" }]);
      expect(fx.seen).toEqual([]);
      expect(fxStand.seen.map((s) => s.url)).toEqual(["/v1/fx-quotes/GBPJPY?amount=7"]);
    } finally {
      await fxStand.close();
      await real.close();
      await stand.close();
      await fx.close();
    }
    nothingRunning(root);
  });

  it("a service that can't be reached is refused as the adapter's Unreachable", async () => {
    const { root } = app();
    // Port 1 on loopback: nothing listens, so the connection is refused at once.
    const got = await inWorld(root, "m2-07-unreachable", { PRICING_BASE_URL: "http://127.0.0.1:1/v1", PRICING_API_KEY: "rates-key-7f3a" }, async (url) => ({ quote: await ask(url, "quote", { pair: "EURUSD", amount: "1" }) }));
    expect(got.quote).toMatchObject({ status: 422, body: { _tag: "RatesUnreachable" } });
    nothingRunning(root);
  });
});

// ---- refusal codes and exits across generated adapters (snag #1012) ----

/** A copy of acme with these adapters generated, installed and mounted under their own names, each `written` edit applied to its `src/written.ts` before generating; no app verbs. */
const bare = (adapters: Readonly<Record<string, ((written: string) => string) | null>>): App => {
  const copy = copyOf(acme);
  apps.push(copy);
  const { root } = copy;
  const scope = join(root, "node_modules/@orthograph");
  rmSync(scope);
  mkdirSync(scope);
  for (const entry of readdirSync(join(acme, "node_modules/@orthograph"))) symlinkSync(join(acme, "node_modules/@orthograph", entry), join(scope, entry));
  mkdirSync(join(root, ".specs"));
  mkdirSync(join(root, "blueprint/adapters"), { recursive: true });
  const pkg = JSON.parse(readFileSync(join(root, "package.json"), "utf8")) as { dependencies: Record<string, string> };
  for (const [name, edit] of Object.entries(adapters)) {
    writeFileSync(join(root, ".specs", `${name}.json`), JSON.stringify(spec(name[0]!.toUpperCase() + name.slice(1), "none", "quotes")));
    ortho(root, "new", "adapter", name, "--from-openapi", join(root, ".specs", `${name}.json`));
    if (edit !== null) {
      const file = join(root, "plugins", name, "src/written.ts");
      const before = readFileSync(file, "utf8");
      const after = edit(before);
      expect(after, `${file}: the edit changed nothing`).not.toBe(before);
      writeFileSync(file, after);
    }
    symlinkSync(join(root, "plugins", name), join(scope, name));
    pkg.dependencies[`@orthograph/${name}`] = "0.0.0";
    writeFileSync(join(root, `blueprint/adapters/${name}.ts`), mountOf(name));
  }
  writeFileSync(join(root, "package.json"), JSON.stringify(pkg, null, 2));
  return copy;
};
const SCAFFOLDED_CODE = "export const code: string | undefined = undefined;";
const codeOf = (code: string) => (written: string) => written.replace(SCAFFOLDED_CODE, `export const code: string | undefined = ${JSON.stringify(code)};`);
/** The prefix of each refusal code the generated model gives the four errors named with `prefix` (`OptionalApiFailure` …), from its `refusals`. */
const codesOf = (root: string, prefix: string) => {
  const { refusals } = JSON.parse(readFileSync(join(root, "generated/model/model.json"), "utf8")) as { refusals: Record<string, string> };
  return Object.fromEntries(FOUR.map((f) => [`${prefix}${f}`, refusals[`${prefix}${f}`]?.split("-")[0]]));
};

describe("07 two generated adapters whose names share their first two letters (snag #1012)", () => {
  it("control: mounted together with neither setting a code, ortho generate refuses, naming the clash and `code`", () => {
    const { root } = bare({ open: null, optional: null });
    const said = run(root, "generate");
    expect(said.status, said.out).not.toBe(0);
    expect(said.out).toMatch(/optional and open .*OP-.*`code`|open and optional .*OP-.*`code`/);
  });

  it("one setting a code in its scaffolded src/written.ts mounts beside the other: its four errors take that prefix, the other's keep the default", () => {
    const { root } = bare({ open: null, optional: codeOf("OQ") });
    ortho(root, "generate");
    expect(codesOf(root, "Optional"), "the refusals of generated/model/model.json").toEqual({ OptionalApiFailure: "OQ", OptionalInputRefused: "OQ", OptionalAnswerRefused: "OQ", OptionalUnreachable: "OQ" });
    expect(codesOf(root, "Open")).toEqual({ OpenApiFailure: "OP", OpenInputRefused: "OP", OpenAnswerRefused: "OP", OpenUnreachable: "OP" });
  });
});

describe("07 one operation calls two generated adapters (snag #1012)", () => {
  it("an operation whose steps call two generated adapters, declaring both adapters' errors, is accepted by ortho generate", () => {
    const { root } = bare({ rates: null, "fx-rates": null });
    const errors = ["Rates", "FxRates"].flatMap((p) => FOUR.map((f) => `${p}${f}`));
    mkdirSync(join(root, "blueprint/things/rate/verbs"), { recursive: true });
    writeFileSync(join(root, "blueprint/things/rate/thing.ts"), THING);
    writeFileSync(join(root, "blueprint/things/rate/verbs/both.ts"), `import { Blueprint } from "orthograph";
import { ${errors.slice(0, 4).join(", ")} } from "@orthograph/rates";
import { ${errors.slice(4).join(", ")} } from "@orthograph/fx-rates";
import rates from "../../../adapters/rates.ts";
import fx from "../../../adapters/fx-rates.ts";
import { Rate } from "../thing.ts";

export default Blueprint.operation(Rate, {
  description: "Ask both mounts for a rate.",
  payload: { pair: Blueprint.text({ max: 20 }), amount: Blueprint.uint(32) },
  answer: { rate: Blueprint.text({ max: 40 }) },
  errors: [${errors.join(", ")}],
  allowed: [Blueprint.anyone],
  steps: { price: Blueprint.step.call(rates.calls.quotes.get), backup: Blueprint.step.call(fx.calls.quotes.get) },
});
`);
    ortho(root, "generate");
    // Not by letting a clash through: the operation's eight refusals have eight exits, so the command line still tells them apart.
    const { things } = JSON.parse(readFileSync(join(root, "generated/model/model.json"), "utf8")) as { things: Record<string, { errors?: Record<string, { exit: number }> }> };
    const exits = errors.map((e) => Object.values(things).find((t) => t.errors?.[e] !== undefined)?.errors?.[e]?.exit);
    expect(exits.every((x) => typeof x === "number"), `each error's exit in the model: ${JSON.stringify(exits)}`).toBe(true);
    expect(new Set(exits).size, `the eight exits: ${JSON.stringify(exits)}`).toBe(8);
  });
});
